class Solution {
public:
    double minimumAverage(vector<int>& nums) {
        sort(nums.begin(), nums.end());
        double ans = 1e9;
        for (int i = 0, j = nums.size() - 1; i < j; i++, j--)
            ans = min(ans, (nums[i] + nums[j]) / 2.0);
        return ans;
    }
};

