class Solution {
public:
    double minimumAverage(vector<int>& nums) {
        multiset<int> s(nums.begin(), nums.end());
        double ans = 1e9;
        while (!s.empty()) {
            int mn = *s.begin(); s.erase(s.begin());
            int mx = *s.rbegin(); s.erase(prev(s.end()));
            ans = min(ans, (mn + mx) / 2.0);
        }
        return ans;
    }
};

