class Solution {
    public double minimumAverage(int[] nums) {
        TreeMap<Integer, Integer> s = new TreeMap<>();
        for (int x : nums) s.merge(x, 1, Integer::sum);
        double ans = Double.MAX_VALUE;
        while (!s.isEmpty()) {
            int mn = s.firstKey(), mx = s.lastKey();
            dec(s, mn); if (mn != mx) dec(s, mx);
            ans = Math.min(ans, (mn + mx) / 2.0);
        }
        return ans;
    }
    private void dec(TreeMap<Integer,Integer> s, int k) {
        if (s.merge(k, -1, Integer::sum) == 0) s.remove(k);
    }
}

